```sql
-- Crear la vista
CREATE VIEW v_contador_alumnos AS
SELECT COUNT(*) AS total_activos
FROM alumnos
WHERE activo = TRUE;

SELECT * FROM v_contador_alumnos;

-- Modificar (reemplazar) la vista
CREATE OR REPLACE VIEW v_contador_alumnos AS
SELECT
  SUM(CASE WHEN activo = TRUE THEN 1 ELSE 0 END) AS total_activos,
  SUM(CASE WHEN activo = FALSE THEN 1 ELSE 0 END) AS total_inactivos
FROM alumnos;

SELECT * FROM v_contador_alumnos;

-- Eliminar la vista
DROP VIEW IF EXISTS v_contador_alumnos;

-- Verificar que se eliminó
SHOW FULL TABLES WHERE Table_type = 'VIEW';
```

```sql
-- 1. Búsqueda por nombre exacto
EXPLAIN SELECT * FROM productos WHERE nombre = 'Laptop';
-- type: ALL (escaneo completo)
-- Necesita: CREATE INDEX idx_nombre ON productos(nombre);

-- 2. Rango de precios
EXPLAIN SELECT * FROM productos WHERE precio > 500;
-- type: ALL (escaneo completo)
-- Necesita: CREATE INDEX idx_precio ON productos(precio);

-- 3. Filtro por categoría + ordenación por precio
EXPLAIN SELECT * FROM productos WHERE id_categoria = 3 ORDER BY precio;
-- type: ALL + Using filesort
-- Necesita: CREATE INDEX idx_categoria_precio ON productos(id_categoria, precio);
-- El índice compuesto filtra por categoría Y ordena por precio sin filesort
```

**Justificación**:
- Índices simples (nombre, precio) son útiles para búsquedas puntuales.
- El índice compuesto (id_categoria, precio) optimiza el filtro Y la ordenación en una sola operación.

