GRANT SELECT, INSERT ON tienda.clientes TO 'app_web'@'localhost';
GRANT SELECT, INSERT ON tienda.pedidos TO 'app_web'@'localhost';
GRANT SELECT, INSERT ON tienda.lineas_pedido TO 'app_web'@'localhost';
-- Solo puede leer productos, crear clientes y pedidos

-- 2. Usuario para el panel de administración
CREATE USER 'admin_tienda'@'localhost' IDENTIFIED BY 'Admin!2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON tienda.* TO 'admin_tienda'@'localhost';
-- Puede gestionar todo excepto estructura

